// src/api/api.js

// ==================================================
// ★ 백엔드 주소
// ==================================================

export const API_BASE_URL =
  "http://localhost:8080";

// ==================================================
// ★ 로그인 토큰 저장/조회
// ==================================================

const TOKEN_KEY = "readlyToken";
const MEMBER_ID_KEY = "readlyMemberId";

export function getToken() {
  return localStorage.getItem(
    TOKEN_KEY
  );
}

export function setToken(token) {
  localStorage.setItem(
    TOKEN_KEY,
    token
  );
}

export function clearToken() {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(
    MEMBER_ID_KEY
  );
}

export function getMemberId() {
  return localStorage.getItem(
    MEMBER_ID_KEY
  );
}

export function setMemberId(id) {
  localStorage.setItem(
    MEMBER_ID_KEY,
    id
  );
}

// ==================================================
// ★ 공통 fetch 래퍼
// ==================================================

export async function apiFetch(
  path,
  options = {}
) {
  const token = getToken();

  const headers = {
    "Content-Type": "application/json",
    ...(options.headers || {}),
  };

  if (token) {
    headers["Authorization"] =
      `Bearer ${token}`;
  }

  const response = await fetch(
    `${API_BASE_URL}${path}`,
    {
      ...options,
      headers,
    }
  );

  let data = null;

  try {
    data = await response.json();
  } catch (parseError) {
    data = null;
  }

  if (!response.ok) {
    const message =
      data?.message ||
      "요청 처리 중 오류가 발생했습니다.";

    throw new Error(message);
  }

  return data;
}

// ==================================================
// ★ 인증 관련 API
//
// ⚠️ 백엔드 실제 경로/필드명에 맞춰 수정됨
// (BE: MemberDto 기준)
// ==================================================

// 요청: { email, password }
// 응답: { memberId, accessToken }
//
// ★ 기존과 다르게 "user" 객체 자체가 없어서
// 이름(name) 등은 로그인 응답만으로는 못 받아옴.
// 필요하면 로그인 성공 후 별도로
// 내 프로필 조회 API를 호출해야 하는데,
// 지금 백엔드에 그 API가 없는 상태 (아래 "백엔드 확인 필요" 참고)
export function login(
  email,
  password
) {
  return apiFetch(
    "/api/members/login",
    {
      method: "POST",
      body: JSON.stringify({
        email,
        password,
      }),
    }
  );
}

// 요청: { loginId, email, password }
//
// ★ "name"(닉네임)은 회원가입 단계에 없음.
// 가입 후 PATCH /api/members/me/profile 로 별도 설정해야 함
export function signup(
  loginId,
  email,
  password
) {
  return apiFetch(
    "/api/members/signup",
    {
      method: "POST",
      body: JSON.stringify({
        loginId,
        email,
        password,
      }),
    }
  );
}

export function logout() {
  clearToken();
  localStorage.removeItem(
    "currentUser"
  );
}
